"""Referee: profile the L8 Thm B points (generated by the REPOSITORY's k6fam code, read-only) with the
referee's own anchored gcd inversion (rlib.contacts_gcd_anchor); cross-check small N with the
residue-class rule on the integral chart."""
import sys
sys.path.insert(0,'/home/user/Jarnik/docs/claude_review/threshold/L8/k6fam')
from fractions import Fraction as Fr
from math import log, lcm
from lift import lift_T
from ell import quotient_curve
from rlib import contacts_gcd_anchor, contacts_classes
xs=[Fr(2),Fr(3),Fr(-5),Fr(1)]
F,C,g,pts=quotient_curve(xs); kk=g[3]; Q1,Q2=pts[0],pts[1]
D=C.add(Q2,(Q1[0],-Q1[1])); R=Q1
for N in range(1,15):
    R=C.add(R,D); L=lift_T(F,R[0]/kk)
    if not L: print(N,'no lift'); continue
    pt=L[0]; P=[xs[0],xs[1],xs[2],pt[0],pt[1],pt[2]]
    if len(set(P))<6: print(N,'degenerate'); continue
    r=[1/(p-P[0]) for p in P[1:]]
    Dn=1
    for v in r: Dn=lcm(Dn,v.denominator)
    X=[int(v*Dn) for v in r]
    d,delta=contacts_gcd_anchor(X)
    lg=[log(v) if v>1 else 0.0 for v in d.values()]
    lo,hi=min(lg),max(lg); eps=(hi-lo)/(hi+lo) if lo>0 else 1.0
    extra=''
    if N<=4:
        dc=contacts_classes(X+[0]) if False else None
    print("%2d w*=%8.2f eps=%.4f delta=%d maxlog|X|=%.1f"%(N,(hi+lo)/2,eps,delta,max(log(abs(x)) for x in X if x)),flush=True)
